from z3 import *

def solve():
    n = 21
    A = [[Bool(f"e_{i}_{j}") if i < j else None for j in range(n)] for i in range(n)]

    for i in range(n):
        for j in range(i):
            A[i][j] = A[j][i]

    s = Solver()

    # Degree constraints
    for i in range(n):
        deg = Sum([If(A[i][j], 1, 0) for j in range(n) if i != j])
        s.add(deg >= 4)
        s.add(deg <= 6)

    # Girth >= 5 constraints
    # No triangles: A[i][j] and A[j][k] => not A[i][k]
    # No 4-cycles: A[i][j] and A[i][k] => j and k have no other common neighbors
    # Equivalently, for any i != j, they share at most 1 neighbor if not adjacent, 0 if adjacent.
    for i in range(n):
        for j in range(i + 1, n):
            common_neighbors = Sum([If(And(A[i][k], A[j][k]), 1, 0) for k in range(n) if k != i and k != j])
            s.add(If(A[i][j], common_neighbors == 0, common_neighbors <= 1))

    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if is_true(m[A[i][j]]):
                    edges.append((i, j))
        print(edges)
    else:
        print("UNSAT")

solve()

