def girth(G):
    min_girth = float('inf')
    for n in G.nodes():
        # BFS
        dist = {n: 0}
        parent = {n: None}
        q = [n]
        while q:
            curr = q.pop(0)
            for neighbor in G.neighbors(curr):
                if neighbor not in dist:
                    dist[neighbor] = dist[curr] + 1
                    parent[neighbor] = curr
                    q.append(neighbor)
                elif parent[curr] != neighbor:
                    min_girth = min(min_girth, dist[curr] + dist[neighbor] + 1)
    return min_girth

print("True girth:", girth(G))
